theorem dotV_add_smul_strict {m d : ℕ} {grad : Fin m → (Fin d → ℝ)} {v w : Fin d → ℝ}
    (hv : ∀ i, dotV (grad i) v ≤ 0) (hw : ∀ i, dotV (grad i) w < 0) {t : ℝ} (ht : 0 < t) :
    ∀ i, dotV (grad i) (v + t • w) < 0

theorem convex_multImprovingSet {m : ℕ} {f : ℝ → ℝ} {g : Fin m → ℝ → ℝ}
    (hf : ConvexOn ℝ Set.univ f) (hg : ∀ i, ConvexOn ℝ Set.univ (g i)) :
    Convex ℝ (multImprovingSet f g)
